address from,
address to,
uint256 tokenId
) public {
require(
iERC721CheckAuth(erc721).isAuthorized(from, msg.sender, tokenId),
"P404: not authorized"
);
IERC721(erc721).safeTransferFrom(from, to, tokenId);
if (to == address(this)) {
transform(tokenId);
}
}

