## Contract Source
```solidity
pragma solidity 0.8.24;

import "./ERC20.sol";
import "./IERC721Metadata.sol";
import "./IERC721Receiver.sol";
import "./IERC165.sol";

interface IERC721Enumerable {
function totalSupply() external view returns (uint256);
function tokenOfOwnerByIndex(
address owner,
uint256 index
) external view returns (uint256);
function tokenByIndex(uint256 index) external view returns (uint256);
}

interface IERC721Burnable {
function burn(uint256 tokenId) external;
}

interface IERC721Mintable {
function mint(address to) external;
}

interface iERC721CheckAuth {
function isAuthorized(
address _owner,
address _spender,
uint256 _tokenId
) external view returns (bool);
}

interface IP404 {

function isValidTokenId(
uint256 _tokenOrAmount
) external view returns (bool);
}

contract P404Token is ERC20, IP404 {
address public erc721;

uint256 public constant MAX_SUPPLY = 300000000 * 10 ** 18;

uint256 public constant MAX_ERC20_TOKENS = 300000000 * 10 ** 18;
uint256 public constant TRANSFORM_PRICE = 10000 * 10 ** 18;
uint256 public constant TRANSFORM_LOSE_RATE = 200;
uint256 public constant MAX_NFT_MINT = 4000;
uint256 public constant MAX_MINT_VALUE = 0.6 ether;

uint256 public constant MINT_PRICE = 0.2 ether;
uint256 public nftMinted;

address public feeTo;

address public owner;

event FromTokenToNFT(address from, uint256 amount);
event FromNFTToToken(address from, uint256 tokenId);
event PayToMint(address from, uint256 price, uint256 tokenId);

mapping(address => bool) public allowlist;

mapping(address => uint256) public mintedAmount;

constructor(
string memory _name,
string memory _symbol,
address _erc721,
address _feeTo
) ERC20(_name, _symbol) {
_mint(msg.sender, 260000000 * 10 ** 18);
erc721 = _erc721;
feeTo = _feeTo;
owner = msg.sender;
}

function batchSetAllowlist(
address[] calldata _addres,
bool _allow
) external {
require(owner == msg.sender, "META: no owner");
for (uint256 i = 0; i < _addres.length; i++) {
allowlist[_addres[i]] = _allow;
}
}

function isValidTokenId(uint256 tokenId) public pure returns (bool) {

return tokenId < 30001;
}

function transferFrom(
address from,
address to,
uint256 value
) public override returns (bool) {
if (isValidTokenId(value)) {
require(
iERC721CheckAuth(erc721).isAuthorized(from, msg.sender, value),
"P404: not authorized"
);
IERC721(erc721).safeTransferFrom(from, to, value);
if (to == address(this)) {
transform(value);
}
} else {
super.transferFrom(from, to, value);
}
return true;
}

function _update(
address from,
address to,
uint256 value
) internal override {

if (!isValidTokenId(value)) {
super._update(from, to, value);
}

if (to == address(this) || to == erc721) {
transform(value);
} else {
if (isValidTokenId(value)) {

if (from != address(0)) {
require(
iERC721CheckAuth(erc721).isAuthorized(
from,
msg.sender,
value
),
"P404: not authorized"
);
}
IERC721(erc721).safeTransferFrom(from, to, value);
}
}
}

function transform(uint256 tokenIdOrValue) internal {
if (isValidTokenId(tokenIdOrValue)) {
_erc721ToErc20(tokenIdOrValue);
} else {
_erc20ToErc721(tokenIdOrValue);
}
}

function approve(
address spender,
uint256 tokenIdOrValue
) public override returns (bool) {
if (isValidTokenId(tokenIdOrValue)) {
IERC721(erc721).approve(spender, tokenIdOrValue);
return true;
} else {
return super.approve(spender, tokenIdOrValue);
}
}

function setApproveForAll(address operator, bool approved) public {
IERC721(erc721).setApprovalForAll(operator, approved);
}

function getApproved(uint256 tokenId) public view returns (address) {
return IERC721(erc721).getApproved(tokenId);
}

function isApprovedForAll(
address _owner,
address operator
) public view returns (bool) {
return IERC721(erc721).isApprovedForAll(_owner, operator);
}

function safeTransferFrom(
address from,
address to,
uint256 tokenId,
bytes memory data
) public {
require(
iERC721CheckAuth(erc721).isAuthorized(from, msg.sender, tokenId),
"P404: not authorized"
);
IERC721(erc721).safeTransferFrom(from, to, tokenId, data);
if (to == address(this)) {
transform(tokenId);
}
}

function safeTransferFrom(
address from,
address to,
uint256 tokenId
) public {
require(
iERC721CheckAuth(erc721).isAuthorized(from, msg.sender, tokenId),
"P404: not authorized"
);
IERC721(erc721).safeTransferFrom(from, to, tokenId);
if (to == address(this)) {
transform(tokenId);
}
}

function ownerOf(uint256 tokenId) public view returns (address) {
return IERC721(erc721).ownerOf(tokenId);
}

function tokenURI(uint256 tokenId) public view returns (string memory) {
return IERC721Metadata(erc721).tokenURI(tokenId);
}

function totalSupplyERC721() public view returns (uint256) {
return IERC721Enumerable(erc721).totalSupply();
}

function tokenOfOwnerByIndex(
address _owner,
uint256 index
) public view returns (uint256) {
return IERC721Enumerable(erc721).tokenOfOwnerByIndex(_owner, index);
}

function tokenByIndex(uint256 index) public view returns (uint256) {
return IERC721Enumerable(erc721).tokenByIndex(index);
}

function _erc20ToErc721(uint256 _amount) internal {

require(_amount >= TRANSFORM_PRICE, "P404: insufficient amount");

require(_amount % TRANSFORM_PRICE == 0, "P404: invalid amount");

uint256 nfts = _amount / TRANSFORM_PRICE;
uint256 _realcost = nfts * TRANSFORM_PRICE;
_burn(address(this), _realcost);
for (uint256 i = 0; i < nfts; i++) {
IERC721Mintable(erc721).mint(msg.sender);
}
emit FromTokenToNFT(msg.sender, _amount);
}

function _erc721ToErc20(uint256 _tokenId) internal {

IERC721Burnable(erc721).burn(_tokenId);
_mint(
msg.sender,
(TRANSFORM_PRICE * (10000 - TRANSFORM_LOSE_RATE)) / 10000
);

emit FromNFTToToken(msg.sender, _tokenId);
}

function mint(address to, uint256 amount) public {
require(msg.sender == erc721, "P404: only nft contract can mint");
require(
totalSupply() + amount <= MAX_SUPPLY,
"P404: exceed max supply"
);
_mint(to, amount);
}

function onERC721Received(
address,
address,
uint256,
bytes calldata
) external pure returns (bytes4) {
return this.onERC721Received.selector;
}

function supportsInterface(bytes4 interfaceId) public pure returns (bool) {
return
interfaceId == type(IERC165).interfaceId ||
interfaceId == type(IERC721Receiver).interfaceId ||
interfaceId == type(IERC20).interfaceId ||
interfaceId == type(IP404).interfaceId;
}

function mintNFT() public payable {
require(msg.value >= MINT_PRICE, "P404: insufficient amount");
require(tx.origin == msg.sender, "P404: not allow contract");

require(allowlist[msg.sender], "P404: not in allowlist");

require(msg.value <= MAX_MINT_VALUE, "P404: too much money, max is 0.6 ether");

uint256 _mint = msg.value / MINT_PRICE;
uint256 realcost = _mint * MINT_PRICE;

require(mintedAmount[msg.sender] + realcost <= MAX_MINT_VALUE, "P404: exceed max mint value");
require(nftMinted + _mint <= MAX_NFT_MINT, "P404: exceed max mint");

for (uint256 i = 0; i < _mint; i++) {
IERC721Mintable(erc721).mint(msg.sender);
}

emit PayToMint(msg.sender, realcost, _mint);
nftMinted += _mint;
mintedAmount[msg.sender] += realcost;

if (feeTo != address(0)) {
payable(feeTo).transfer(realcost);
}

uint256 refund = msg.value - realcost;
if (refund > 0) {
payable(msg.sender).transfer(refund);
}
}

receive() external payable {
mintNFT();
}
}
```

## Fuzzing task — strategy: reentrancy_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Detect reentrancy vulnerabilities (CEI pattern violations).

**Technique:**
Scan the ABI for functions that SEND ETH OUT to msg.sender (typical name patterns: withdraw*, claim*, redeem*, unstake*, cashOut*, emergencyWithdraw*, *ETH, *Funds, harvest*, payout* — but use whatever names this ABI actually has). Configure attacker reentry on one of those functions, fund the contract via a PAYABLE function (typical names: deposit*, stake*, mint*, fund*, buy*, contribute*), then trigger the ETH-sending function so the attacker's receive() callback re-enters. DO NOT default to the names in the example below — they are placeholders.

**Value hints:** Use "0xde0b6b3a7640000" (1 ETH) for payable calls. Use "0x0" for non-payable.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Strategy notes:** Use "atk.setReentrantCall" as the FIRST call to arm the attacker's re-entry callback: ["atk.setReentrantCall", {"reentrant_func": "fnName", "reentrant_args": ["0x..."], "max_count": 3}, "0x0", "attacker_address"]. The attacker re-enters whenever the target calls BACK into it — either by sending it ETH (receive) or by invoking an unknown selector on it (fallback: e.g. an ERC777/hook/migration callback) — so this covers callback-driven reentrancy too, not just native-ETH transfers. reentrant_func is the function re-called during that callback: a BARE function name from THIS target's ABI (no parentheses, no type list; re-entry always hits the main contract, never an external var). reentrant_args matches that function's input types (use [] if no args). max_count is the re-entry depth (1-5). There is ONE attacker identity: route the arm, the funding/setup AND the final trigger call all through attacker_address (the unified attacker contract) so the callback fires with the attacker as msg.sender.
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

